using Microsoft.AspNetCore.Components.Web;

namespace sv_44b63954351a42219b3c9ce666e77bde.Auth;

/// <summary>
/// Server-side AuthenticationStateProvider that simulates a logged-in user
/// and persists the auth state so the WebAssembly runtime can pick it up.
/// </summary>
public sealed class PersistingServerAuthStateProvider : ServerAuthenticationStateProvider, IDisposable
{
    private readonly PersistentComponentState _state;
    private PersistingComponentStateSubscription _subscription;
    private Task<AuthenticationState>? _authenticationStateTask;

    public PersistingServerAuthStateProvider(PersistentComponentState state)
    {
